struct EmptyBuilder;
struct WithName { name: String };
struct Complete { name: String, age: u32 };

impl EmptyBuilder {
    fn name(self, name: &str) -> WithName {
        WithName { name: name.to_string() }
    }
}
impl WithName {
    fn age(self, age: u32) -> Complete {
        Complete { name: self.name, age }
    }
}

fn main() {
    let person = EmptyBuilder.name("TypeState").age(30);
    println!("{} is {} years old", person.name, person.age);
}
